try: r.load("old", password="pw")
except ValueError as e: assert "不可恢复的旧记录" in str(e)
else: raise AssertionError("legacy")

# invalid inputs
for fn in [lambda: r.load("nope"), lambda: r.load("k", 99, password="pw"),
           lambda: r.load("k", 0, password="pw"), lambda: r.seal("", "x"),
